import { sql } from "drizzle-orm";
import {
  boolean,
  customType,
  index,
  integer,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  vector,
} from "drizzle-orm/pg-core";

/** nomic-embed-text produces 768-dimensional vectors. Changing models means a new migration. */
export const EMBEDDING_DIMENSIONS = 768;

// Drizzle has no built-in tsvector type, so we declare it. It is only ever generated by Postgres.
const tsvector = customType<{ data: string }>({
  dataType: () => "tsvector",
});

export const users = pgTable("users", {
  id: uuid("id").primaryKey().defaultRandom(),
  email: text("email").notNull().unique(),
  name: text("name").notNull(),
  passwordHash: text("password_hash").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

/**
 * Access control lives in Postgres row-level security (see drizzle/0001_row_level_security.sql), not in app code:
 * a user sees documents they own, plus documents shared with the whole team.
 */
export const documents = pgTable(
  "documents",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    ownerId: uuid("owner_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    shared: boolean("shared").notNull().default(false),
    title: text("title").notNull(),
    source: text("source").notNull(),
    // sha256 of the raw text — re-ingesting the same file is a no-op instead of duplicating chunks.
    contentHash: text("content_hash").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  // Unique per owner, not globally: two people may upload the same file privately.
  (t) => [uniqueIndex("documents_owner_hash_idx").on(t.ownerId, t.contentHash)],
);

export const chunks = pgTable(
  "chunks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    documentId: uuid("document_id")
      .notNull()
      .references(() => documents.id, { onDelete: "cascade" }),
    chunkIndex: integer("chunk_index").notNull(),
    // Nearest markdown heading above the chunk — shown in citations ("Expense Policy › Travel").
    heading: text("heading"),
    content: text("content").notNull(),
    embedding: vector("embedding", { dimensions: EMBEDDING_DIMENSIONS }).notNull(),
    // Full-text search column, computed and kept in sync by Postgres itself.
    searchVector: tsvector("search_vector").generatedAlwaysAs(
      sql`to_tsvector('english', coalesce(heading, '') || ' ' || content)`,
    ),
  },
  (t) => [
    // HNSW = approximate nearest-neighbour index; cosine distance matches how nomic embeddings are compared.
    index("chunks_embedding_hnsw_idx").using("hnsw", t.embedding.op("vector_cosine_ops")),
    index("chunks_search_vector_gin_idx").using("gin", t.searchVector),
    index("chunks_document_id_idx").on(t.documentId),
  ],
);

export type User = typeof users.$inferSelect;
export type Document = typeof documents.$inferSelect;
export type Chunk = typeof chunks.$inferSelect;
